function setArtworkInputs(){const d=designDraft;$('#artMode').value=d.mode||'color';$('#artFit').value=d.fit||'cover';$('#artZoom').value=d.zoom??1;$('#artX').value=d.x??50;$('#artY').value=d.y??50}
